sp_widget.client_script:
api.controller = function($scope, $window, $filter) {
  var c = this;

  c.searchText = '';
  c.itemsPerPage = "5"; 
  c.currentPage = 1;
  c.sortField = 'closed_at';
  c.sortReverse = true; 

  c.filteredList = [];
  c.pagedList = [];
  c.pages = [];

  c.updatePagination = function() {
    c.filteredList = $filter('filter')(c.data.list, c.searchText);
    c.filteredList = $filter('orderBy')(c.filteredList, c.sortField, c.sortReverse);

    var perPage = parseInt(c.itemsPerPage, 10);
    c.totalPages = Math.ceil(c.filteredList.length / perPage) || 1;

    if (c.currentPage > c.totalPages) {
      c.currentPage = c.totalPages;
    }

    c.startEntry = c.filteredList.length === 0 ? 0 : (c.currentPage - 1) * perPage + 1;
    c.endEntry = Math.min(c.currentPage * perPage, c.filteredList.length);
    c.pagedList = c.filteredList.slice(c.startEntry - 1, c.endEntry);

    c.pages = [];
    for (var i = 1; i <= c.totalPages; i++) {
      c.pages.push(i);
    }
  };

  c.changeSort = function(field) {
    if (c.sortField === field) {
      c.sortReverse = !c.sortReverse;
    } else {
      c.sortField = field;
      c.sortReverse = false;
    }
    c.updatePagination();
  };

  c.setPage = function(pageNumber) {
    if (pageNumber >= 1 && pageNumber <= c.totalPages) {
      c.currentPage = pageNumber;
      c.updatePagination();
    }
  };

  c.goBack = function() {
    $window.location.href = '/uclm?id=uclm_limit_swap_dashboard';
  };

  if (c.data.list) {
    c.updatePagination();
  }
};

