.clm-empty-state p { color: #64748b; font-size: 14px; margin: 0; }

sp_widget.script:
(function() {
  data.list = [];
  var userId = gs.getUserID();

  var swapGR = new GlideRecord('x_birl3_clm_limit_swap');

  // CRITICAL: This line forces the database to ONLY return records where state is 'approved'
  swapGR.addQuery('state', 'approved'); 

  swapGR.orderByDesc('closed_at'); 
  swapGR.query();

  while (swapGR.next()) {
    data.list.push({
      sys_id: swapGR.getUniqueValue(),
      number: swapGR.getValue('number') || '',
      pan: swapGR.getDisplayValue('pan') || '',
      donee_site: swapGR.getDisplayValue('donee_site') || '',
      donee_amount: parseFloat(swapGR.getValue('donee_amount') || 0),
      donor_site: swapGR.getDisplayValue('donor_site') || '',
      requested_by: swapGR.getDisplayValue('requested_by') || '',
      closed_at: swapGR.getDisplayValue('closed_at') || swapGR.getDisplayValue('sys_updated_on')
    });
  }
})();
